sys_script.script:
//Defect MSSRBXSN-2802 - Disabling this BR and activating the older BR which was disabled before - mss.symphony_process_message_response
(function executeRule(current, previous /*null when async*/ ) {

    var encryptedMsgId = current.encrypted_message_id;
    var eLog = new GlideRecord("x_hsb11_mss_smh_hsbc_symphony_message_log");
    var taskId = current.servicenow_task_id;
    if (current.state == "Processed") {
        eLog.addQuery("servicenow_task_id", taskId);
		eLog.addQuery("encrypted_message_id", '=', null);
		eLog.addQuery("type", current.type);
        eLog.query();
        if (eLog.next()) {
            eLog.state = "Processed";
            eLog.update();
        }
        var tradeTask = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
        tradeTask.addQuery("number", taskId.number);
        tradeTask.query();
        if (tradeTask.next()) {
            tradeTask.encryptedmessageid = encryptedMsgId;
            tradeTask.state = 3; // updating the task state to closed successful
            tradeTask.update();
        }

        var parent = new GlideRecord("x_hsb11_mss_smh_parent_aggregated_trade_chat_queue");
        parent.addQuery("trade_task_reference", taskId.number);
        parent.query();
        if (parent.next()) {
            parent.encryptedmessageid = encryptedMsgId;
            parent.update();
        }

    } else if (current.state == "Error") {
        var tradetaskError = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
        tradetaskError.addQuery("number", taskId.number);
        tradetaskError.query();
        if (tradetaskError.next()) {
            tradetaskError.state = 7; // updating the task state to Cancelled
            tradetaskError.update();
        }


		eLog.addQuery("servicenow_task_id", taskId);
		eLog.addQuery("encrypted_message_id", '=', null);
		eLog.addQuery("type", current.type);
        eLog.query();
        if (eLog.next()) {
			eLog.state = "Error";
			eLog.response_code = current.response_code;
			eLog.response_body = current.error_body;
			eLog.response_date = new GlideDateTime();
            eLog.update();
		}

        // Calls the rest message configured to send widget failture details to ITID instance and creates an Event
        var failureDescription = encodeURIComponent("HSBC MSS iQube Widget failure, details of the error are as below - ServiceNow Reference -" + current.servicenow_task_id.number + " Timestamp : " + current.response_date + "Error code - " + current.response_code + "Error Body - " + current.error_body);
        var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_Symphony');
    }

})(current, previous);
